from lesson_helpers import *
from bs4 import BeautifulSoup
import re
pops=[]
def add(k,title,body,ids):pops.append('<template data-pop="'+k+'" data-title="'+html.escape(title,quote=True)+'">'+body+ref(*ids)+'</template>')
summary=[('D77* est une manifestation à relier à une maladie causale ; volume, fibrose et hypersplénisme ne sont pas synonymes.','CH-CIM'),('Documenter une exposition compatible ; aucune incidence suisse directe D77 n’est retenue.','EU-CLIN'),('Les œufs et la réponse tissulaire contribuent à la fibrose périportale et à une hypertension présinusoïdale.','INT-HSS-MEC'),('Urgence d’abord, puis infection, organes et profil sanguin : chaque examen répond à une question.','EU-DX'),('Dates, lieux, eau douce, traitements, saignements et autres médicaments changent le raisonnement.','EU-CLIN'),('Une fonction hépatique préservée et l’absence d’ascite n’excluent pas des varices graves.','INT-HSS-MEC'),('Les regroupements cliniques orientent ; ils ne démontrent pas un mécanisme unique de cytopénie.','INT-HSS-MEC'),('Croiser preuve parasitaire et atteinte hépatoportale ; sérologie seule insuffisante pour l’activité.','EU-DX'),('Numération, parasitologie, Doppler et endoscopie mesurent des dimensions différentes.','INT-HSS-DX'),('Une hypertension non cirrhotique n’est pas automatiquement une PSVD ; schistosomiase exclue de sa définition.','EU-EASL-BOUND'),('Traiter infection et complications ; ni splénectomie automatique ni transposition aveugle de la cirrhose.','INT-HSS-TX'),('Suivi adapté, réexpositions et prévention après splénectomie ; sérologie persistante n’est pas synonyme d’échec.','EU-FOLLOW'),('Exposition, infection, circulation, numération et plan doivent rester visibles dans la conclusion.','EU-DX'),('Un RCP étranger ne devient pas une FI suisse et une incertitude ne devient pas une certitude.','EU-PRAZI-RCP')]
path=CH/'D77_a.html';txt=path.read_text()
for i,(essential,sid) in enumerate(summary,1):
 m=re.search(r'(<section\b[^>]*id="d77-'+str(i)+r'"[^>]*>)(.*?)(</section>)',txt,re.S);assert m
 soup=BeautifulSoup(m[2],'html.parser');title=soup.find(['h2','h3']).get_text(' ',strip=True);paras=re.findall(r'<p>(.*?)</p>',m[2],re.S)[:2]
 urls={a.get('href') for a in soup.select('a[data-reference-source]')};refs=list(dict.fromkeys(a.get_text().split(' — ')[0] for a in soup.select('a[data-reference-source]')))
 add('d77-exp-'+str(i),'Comprendre — '+title,'<p><b>Lecture expliquée.</b> '+essential+'</p>'+''.join('<p>'+p+'</p>' for p in paras),refs)
 add('pareto-d77-'+str(i),'Essentiel — '+title,'<p>'+essential+'</p>'+key('Revenir au mécanisme et au niveau de preuve avant de décider.'),(sid,))
 entry='<p>'+w('exp-'+str(i),'Comprendre ce point')+' <button class="pareto-btn ui" data-k="pareto-d77-'+str(i)+'">▲ Loi de Pareto — l’essentiel</button></p>'
 txt=txt[:m.end(2)]+entry+txt[m.end(2):]
cases=[('Une hématémèse avec enzymes peu perturbées', '<p>Une personne exposée en zone d’endémie a une grosse rate, des plaquettes basses et un vomissement sanglant. La fonction hépatique peut rester relativement conservée dans HSS : cette information ne neutralise pas le risque. Évaluer sans délai saignement et état circulatoire, puis la source et les complications avec l’équipe appropriée.</p><p>Le traitement oral du parasite et un contrôle de sérologie ne remplacent pas la filière urgente. L’absence de tachycardie sous propranolol ne garantit pas l’absence de perte sanguine.</p>',('INT-HSS-MEC','FI-PROPRANOLOL')),
('Une sérologie encore positive après traitement','<p>Une personne traitée présente encore une sérologie positive, sans nouveau symptôme rapporté. Ce résultat ne démontre pas seul une infection active ou un échec. Revoir calendrier, exposition, résultats directs et suivi approprié avec le spécialiste.</p><p>Le consensus espagnol propose une réévaluation globale vers trois mois, avec adaptation clinique. Ne pas prescrire automatiquement une nouvelle dose à 28 jours sur la base d’un seul cas publié.</p>',('EU-FOLLOW','CH-RMS-DX')),
('Le médicament accessible n’est pas encore identifié','<p>Un projet de praziquantel est établi, mais la pharmacie doit préciser l’approvisionnement. Les recherches datées Swissmedic/AmiKo n’ont pas fourni d’entrée ; il faut vérifier le produit, son information et les conditions d’accès. Le RCP français fournit une référence étrangère, sans démontrer une disponibilité suisse.</p><p>En présence d’allaitement, expliquer la différence entre politique OMS et RCP français, puis décider avec le spécialiste selon le produit réel. Ne pas fusionner les deux formulations.</p>',('CH-PRAZI-STATUS','CH-IMPORT','EU-PRAZI-RCP','INT-WHO')),
('Fièvre après splénectomie','<p>Une personne splénectomisée a de la fièvre un soir. Le protocole CHUV insiste sur un contact urgent et l’absence d’attente nocturne. Utiliser la réserve antibiotique déjà prescrite selon son plan si l’avis n’est pas accessible rapidement, puis poursuivre l’évaluation.</p><p>Ce cas ne justifie pas de donner à toute personne avec une grande rate un diagnostic d’asplénie ou une dose antibiotique universelle.</p>',('CH-CHUV-ASPLEN','CH-CHUV-FEVER'))]
for i,(title,body,refs) in enumerate(cases,1):add('d77-cas-'+str(i),'Cas '+str(i)+' — '+title,'<p><b>Exercice fictif original.</b></p>'+body,refs)
add('d77-calcul-dose','Calcul pédagogique : mg/kg et quantité totale','''<p><b>Exemple fictif, sans prescription.</b> Pour une masse de 60 kg et un schéma étranger de 40 mg/kg sur 24 heures, la quantité arithmétique est 60 × 40 = 2 400 mg. Le kilogramme s’annule : le résultat est une masse totale de médicament, pas une dose en mg/kg ni une décision de nombre de comprimés.</p><p>Le choix du schéma dépend de l’espèce, du produit réel, de l’âge, des organes et des interactions. La formulation et l’arrondi doivent être vérifiés. Le RCP français distingue notamment 40 et 60 mg/kg selon l’espèce et fixe 4–6 heures entre prises répétées le même jour ; une opération correcte ne valide pas la prescription.</p>''',('EU-PRAZI-RCP',))
add('d77-calcul-pouls','Calcul pédagogique : baisse relative de fréquence','''<p><b>Exemple fictif.</b> Une fréquence initiale au repos de 80/min diminuée de 25 % donne 80 × (1 − 0,25) = 60/min. Le pourcentage se calcule sur la valeur initiale. Ce résultat illustre l’objectif mentionné dans la FI du propranolol ; il ne commande pas une augmentation automatique.</p><p>Pression, symptômes, perfusion, contre-indications et tolérance comptent. La FI demande de ne pas augmenter si la fréquence est déjà de 50–55/min ; la sécurité peut imposer une adaptation avant cette borne. Le maximum de dose n’est pas une cible routinière.</p>''',('FI-PROPRANOLOL',))
quiz=[('Une fonction hépatique conservée exclut-elle une hémorragie portale grave ?','Non, la HSS peut associer fonction relativement préservée et varices.','Oui, elle exclut les varices.','La circulation portale et la fonction hépatocellulaire sont des dimensions distinctes.','INT-HSS-MEC'),('Une sérologie positive démontre-t-elle seule l’activité ou l’échec du traitement ?','Non, elle peut persister et doit être interprétée avec les autres données.','Oui, elle suffit à imposer une nouvelle dose.','La preuve directe, le calendrier et les réexpositions orientent le suivi.','EU-FOLLOW'),('Le RCP français de Biltricide est-il une FI suisse ?','Non, sa provenance étrangère et le produit accessible doivent être explicités.','Oui, il prouve l’autorisation suisse.','Le statut daté, l’accès légal et l’information du produit réel restent à vérifier.','CH-PRAZI-STATUS'),('Toute thrombocytopénie avec grosse rate impose-t-elle une splénectomie ?','Non, il faut caractériser mécanismes, complications et alternatives.','Oui, le chiffre suffit.','Les décisions HSS sont spécialisées ; la splénectomie crée notamment un risque infectieux durable.','INT-HSS-TX')]
q=''.join('<div class="quiz ui"><p>'+question+'</p><button data-ok="1">'+yes+'</button><button data-ok="0">'+no+'</button><p class="fb" hidden>'+ex+'</p></div>'+ref(sid) for question,yes,no,ex,sid in quiz)
txt=txt.replace('</div></div>',sec('entrainement','S’entraîner : quatre décisions et quatre cas',q+'<p>'+ ' '.join(w('cas-'+str(i),'Cas '+str(i)) for i in range(1,5))+'</p>',('CH-PROFILES','CH-MEBEKO'))+'</div></div>',1);path.write_text(txt)
path=CH/'D77_d.html';txt=path.read_text();txt=txt.replace('</div></div></div></template>','<p>'+w('calcul-dose','Calculer une quantité en mg/kg')+' '+w('calcul-pouls','Calculer une baisse de fréquence')+'</p></div></div></div></template>');path.write_text(txt)
save('pop1','\n'.join(pops[:16]));save('pop2','\n'.join(pops[16:]));assert len(pops)==34
print('D77 : 34 fenêtres, 14 Pareto, quatre quiz et quatre cas.')
